import numpy as np
from PIL import Image
A=np.load('source_pixels.npz')['rgb']
# print components white pixels, restrict table interior and left of 122.
try:
 import cv2
 for t in list(range(0,20,2))+list(range(20,96,5)):
  a=A[t]
  mx=np.max(a,2); mn=np.min(a,2)
  mask=(mn>175)&((mx-mn)<45)
  # table region broad x30..190 y40..130, focus x<122; avoid yellow border using low chroma criterion
  Y,X=np.ogrid[:144,:256]; mask &= (X>25)&(X<122)&(Y>45)&(Y<133)
  n,lab,stats,cent=cv2.connectedComponentsWithStats(mask.astype('uint8'))
  comps=[]
  for i in range(1,n):
   x,y,w,h,area=stats[i];
   if area>=2: comps.append((area,tuple(np.round(cent[i],1)),(x,y,w,h)))
  print(t+1, sorted(comps,reverse=True)[:8])
except Exception as e:print(e)
PY"
